import { storage } from '../controller/firebase';
import { uploadDocxToGoogleDocs, signInToGoogle } from './googleDriveUpload';
import { ref, uploadBytes, getDownloadURL } from 'firebase/storage';

// Global functions for modal buttons
const closeDocxModal = () => {
  const modal = document.getElementById('docx-preview-modal');
  if (modal) {
    modal.remove();
  }
};

const downloadDocxFromModal = () => {
  const modal = document.getElementById('docx-preview-modal');
  if (modal && modal.docxBlob) {
    const url = URL.createObjectURL(modal.docxBlob);
    const a = document.createElement('a');
    a.href = url;
    a.download = modal.docxFileName || 'document.docx';
    a.click();
    URL.revokeObjectURL(url);
  }
};

// Expose to window for onclick handlers
window.closeDocxModal = closeDocxModal;
window.downloadDocxFromModal = downloadDocxFromModal;

/**
 * Open DOCX file in modal with Google Docs Viewer
 * @param {Blob} docxBlob - DOCX file blob
 * @param {string} title - Modal title
 */
export const openDocxInPopup = async (docxBlob, title = 'Document Preview') => {
  try {
    console.log("📄 Creating DOCX preview modal...");
    
    // Create modal with loading
    const modal = createModalOverlay(title, true);
    document.body.appendChild(modal);
    
    const loading = modal.querySelector('#loading');
    const iframeContainer = modal.querySelector('#iframe-container');
    
    try {
      // Upload to Firebase Storage
      loading.querySelector('span').textContent = 'Uploading document...';
      
      const fileName = `temp_preview/${Date.now()}_${title.replace(/[^a-z0-9]/gi, '_')}.docx`;
      const storageRef = ref(storage, fileName);
      
      console.log("� Uploading to Firebase Storage...");
      await uploadBytes(storageRef, docxBlob);
      
      // Get public download URL
      const downloadURL = await getDownloadURL(storageRef);
      console.log("✅ Upload complete:", downloadURL);
      
      // Use Google Docs Viewer (official embed method)
      // Format: https://docs.google.com/viewer?url=FILE_URL&embedded=true
      const viewerURL = `https://docs.google.com/viewer?url=${encodeURIComponent(downloadURL)}&embedded=true`;
      
      console.log("🔗 Google Docs Viewer URL:", viewerURL);
      
      // Update iframe
      const iframe = iframeContainer.querySelector('iframe');
      iframe.src = viewerURL;
      
      // Show iframe after delay for Google Docs Viewer to fetch and render
      setTimeout(() => {
        loading.style.display = 'none';
        iframeContainer.style.display = 'block';
        console.log('✅ Google Docs Viewer displayed');
      }, 2000); // 2 seconds for Google to fetch and start rendering
      
      // Also listen for load event
      iframe.onload = () => {
        loading.style.display = 'none';
        iframeContainer.style.display = 'block';
        console.log('✅ Google Docs Viewer loaded (onload)');
      };
      
      // Handle iframe error
      iframe.onerror = () => {
        loading.innerHTML = `
          <div style="text-align: center; color: #e53e3e;">
            <div style="font-size: 48px; margin-bottom: 16px;">⚠️</div>
            <div style="font-size: 18px; font-weight: 600; margin-bottom: 8px;">Failed to load viewer</div>
            <div style="font-size: 14px; color: #666; margin-bottom: 16px;">Google Docs Viewer could not load the file</div>
            <button class="btn btn-download" onclick="downloadDocxFromModal()">
              ⬇️ Download instead
            </button>
          </div>
        `;
      };
      
    } catch (error) {
      console.error('❌ Failed to upload/preview DOCX:', error);
      loading.innerHTML = `
        <div style="text-align: center; color: #e53e3e;">
          <div style="font-size: 48px; margin-bottom: 16px;">⚠️</div>
          <div style="font-size: 18px; font-weight: 600; margin-bottom: 8px;">Failed to upload document</div>
          <div style="font-size: 14px; color: #666; margin-bottom: 16px;">${error.message}</div>
          <button class="btn btn-download" onclick="downloadDocxFromModal()">
            ⬇️ Download instead
          </button>
        </div>
      `;
    }
    
    // Store blob for download
    modal.docxBlob = docxBlob;
    modal.docxFileName = title.replace(/[^a-z0-9]/gi, '_') + '.docx';
    
    return modal;
    
  } catch (error) {
    console.error('❌ Failed to create DOCX modal:', error);
    throw error;
  }
};

/**
 * Open PDF blob in a new window for preview
 * @param {Blob} pdfBlob - PDF file blob
 * @param {string} title - Window title
 */
export const openPdfInPopup = (pdfBlob, title = 'PDF Preview') => {
  try {
    const url = URL.createObjectURL(pdfBlob);
    const pdfWindow = window.open(url, '_blank', 'width=800,height=600');
    if (pdfWindow) {
      pdfWindow.document.title = title;
      // Revoke URL when the window is closed
      pdfWindow.addEventListener('beforeunload', () => {
        URL.revokeObjectURL(url);
      });
    } else {
      // Fallback for browsers that block popups
      URL.revokeObjectURL(url); // Clean up immediately
      alert('Popup blocked. Please allow popups for this site to preview the PDF.');
    }
  } catch (error) {
    console.error('Failed to open PDF in popup:', error);
  }
};

const createModalOverlay = (title, isLoading = false) => {
  const modal = document.createElement('div');
  modal.id = 'docx-preview-modal';
  modal.style.cssText = `
    position: fixed;
    inset: 0;
    z-index: 9999;
    background: rgba(0, 0, 0, 0.5);
    backdrop-filter: blur(4px);
    display: flex;
    align-items: center;
    justify-content: center;
    padding: 20px;
  `;
  
  modal.innerHTML = `
    <div style="
      background: white;
      width: 100%;
      max-width: 1200px;
      height: 90vh;
      border-radius: 12px;
      display: flex;
      flex-direction: column;
      box-shadow: 0 20px 60px rgba(0,0,0,0.3);
      overflow: hidden;
    ">
      <!-- Header -->
      <div style="
        background: linear-gradient(135deg, #667eea 0%, #764ba2 100%);
        color: white;
        padding: 16px 24px;
        display: flex;
        justify-content: space-between;
        align-items: center;
        flex-shrink: 0;
      ">
        <h1 style="
          font-size: 18px;
          font-weight: 600;
          margin: 0;
        ">📄 ${title}</h1>
        <div style="display: flex; gap: 8px;">
          <button class="btn btn-download" onclick="downloadDocxFromModal()">
            ⬇️ Download
          </button>
          <button class="btn" onclick="closeDocxModal()">
            ✖️ Close
          </button>
        </div>
      </div>
      
      <!-- Content -->
      <div style="
        flex: 1;
        overflow: hidden;
        background: #f5f5f5;
        position: relative;
      ">
        <!-- Loading -->
        <div id="loading" style="
          display: ${isLoading ? 'flex' : 'none'};
          flex-direction: column;
          align-items: center;
          justify-content: center;
          height: 100%;
          color: #667eea;
          font-size: 16px;
          padding: 40px;
        ">
          <div class="spinner" style="
            border: 4px solid rgba(102, 126, 234, 0.1);
            border-top: 4px solid #667eea;
            border-radius: 50%;
            width: 48px;
            height: 48px;
            animation: spin 1s linear infinite;
            margin-bottom: 16px;
          "></div>
          <span>Loading document...</span>
        </div>
        
        <!-- Google Docs Viewer iframe -->
        <div id="iframe-container" style="
          display: none;
          width: 100%;
          height: 100%;
        ">
          <iframe
            style="
              width: 100%;
              height: 100%;
              border: none;
              background: white;
            "
            title="Document Preview"
          ></iframe>
        </div>
      </div>
    </div>
    
    <style>
      @keyframes spin {
        0% { transform: rotate(0deg); }
        100% { transform: rotate(360deg); }
      }
      
      .btn {
        background: rgba(255,255,255,0.2);
        border: 1px solid rgba(255,255,255,0.3);
        color: white;
        padding: 8px 16px;
        border-radius: 6px;
        cursor: pointer;
        font-size: 14px;
        font-weight: 500;
        transition: all 0.2s;
        font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', sans-serif;
      }
      
      .btn:hover {
        background: rgba(255,255,255,0.3);
        border-color: rgba(255,255,255,0.5);
      }
      
      .btn-download {
        background: rgba(255,255,255,0.9);
        color: #667eea;
      }
      
      .btn-download:hover {
        background: white;
      }
    </style>
  `;
  
  // Close on backdrop click
  modal.addEventListener('click', (e) => {
    if (e.target === modal) {
      closeDocxModal();
    }
  });
  
  // Close on ESC key
  const handleEsc = (e) => {
    if (e.key === 'Escape') {
      closeDocxModal();
      document.removeEventListener('keydown', handleEsc);
    }
  };
  document.addEventListener('keydown', handleEsc);
  
  return modal;
};

